// Validate + normalize a GoHighLevel "Webhook" action payload (Roofing Free Estimate Form).
// Every field is optional: missing / null / "" values become "" instead of breaking the flow.

// ---- Editable lists -------------------------------------------------------
const DEFAULT_COUNTRY_CODE = '1'; // used when a 10-digit number arrives without a "+"
const DISPOSABLE_DOMAINS = [
  'mailinator.com', 'guerrillamail.com', 'guerrillamail.net', 'sharklasers.com', 'grr.la',
  '10minutemail.com', '10minutemail.net', 'tempmail.com', 'temp-mail.org', 'temp-mail.io',
  'tempmailo.com', 'tempr.email', 'throwawaymail.com', 'yopmail.com', 'yopmail.net',
  'trashmail.com', 'trashmail.de', 'getnada.com', 'nada.email', 'dispostable.com',
  'maildrop.cc', 'mailnesia.com', 'mintemail.com', 'mohmal.com', 'fakeinbox.com',
  'spamgourmet.com', 'emailondeck.com', 'burnermail.io', 'mailcatch.com', 'moakt.com',
  'discard.email', 'tempinbox.com', 'getairmail.com', 'inboxkitten.com', 'mail.tm',
  'emailfake.com', 'fakemail.net', 'mytemp.email', 'spambox.us', 'trbvm.com',
];
const SPAM_PHRASES = [
  'seo service', 'backlink', 'crypto', 'bitcoin', 'casino', 'viagra', 'cialis', 'forex',
  'loan offer', 'web design service', 'guest post', 'rank your website', 'first page of google',
];
// ---------------------------------------------------------------------------

const raw = $input.first().json;
const b = (raw && typeof raw.body === 'object' && raw.body !== null) ? raw.body : (raw || {});
const obj = (v) => (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
const c = obj(b.contact);
const loc = obj(b.location);
const custom = obj(b.customData);
const trig = obj(b.triggerData);

const str = (v) => {
  if (v === undefined || v === null) return '';
  if (typeof v === 'object') return '';
  const s = String(v).trim();
  return (s.toLowerCase() === 'null' || s.toLowerCase() === 'undefined') ? '' : s;
};
const pick = (...vals) => {
  for (const v of vals) {
    const s = str(v);
    if (s) return s;
  }
  return '';
};
// Case-insensitive lookup of a form field in body, customData or triggerData.
const field = (...names) => {
  const wanted = names.map((n) => n.toLowerCase());
  for (const src of [b, custom, trig]) {
    for (const k of Object.keys(src)) {
      if (wanted.includes(k.trim().toLowerCase())) {
        const s = str(src[k]);
        if (s) return s;
      }
    }
  }
  return '';
};

// ---- Names ----
const fullNameRaw = pick(b.full_name, b.fullName, b.name, c.full_name, c.name).replace(/\s+/g, ' ');
let firstName = pick(b.first_name, b.firstName, c.first_name, c.firstName);
let lastName = pick(b.last_name, b.lastName, c.last_name, c.lastName);
if (!lastName && fullNameRaw) {
  if (firstName && fullNameRaw.toLowerCase().startsWith(firstName.toLowerCase() + ' ')) {
    lastName = fullNameRaw.slice(firstName.length).trim();
  } else if (!firstName) {
    const parts = fullNameRaw.split(' ');
    firstName = parts.shift() || '';
    lastName = parts.join(' ');
  }
}
if (!firstName && !lastName && fullNameRaw) firstName = fullNameRaw;
const fullName = [firstName, lastName].filter(Boolean).join(' ') || fullNameRaw;

// ---- Email ----
const emailRaw = pick(b.email, c.email).toLowerCase().replace(/\s+/g, '');
const emailOk = /^[a-z0-9._%+'-]+@[a-z0-9-]+(\.[a-z0-9-]+)*\.[a-z]{2,}$/.test(emailRaw);
const email = emailOk ? emailRaw : '';
const emailDomain = email ? email.split('@')[1] : '';
const isDisposable = !!emailDomain && DISPOSABLE_DOMAINS.some((d) => emailDomain === d || emailDomain.endsWith('.' + d));

// ---- Phone -> +digits ----
const phoneRaw = pick(b.phone, c.phone);
let digits = phoneRaw.replace(/\D/g, '');
if (digits.startsWith('00')) digits = digits.slice(2);
if (!phoneRaw.startsWith('+') && !phoneRaw.startsWith('00') && digits.length === 10 && DEFAULT_COUNTRY_CODE) {
  digits = DEFAULT_COUNTRY_CODE + digits;
}
const phoneJunk = /^(\d)\1+$/.test(digits) || /(0123456789|1234567890|9876543210)/.test(digits);
const phoneOk = digits.length >= 8 && digits.length <= 15 && !phoneJunk;
const phone = phoneOk ? '+' + digits : '';

// ---- Roofing form fields ----
const helpTopic = field('How can we help?', 'how_can_we_help', 'how can we help');
const message = field('Message', 'message');
const website = field('Your website', 'your_website', 'website');
const propertyAddress = field('Property Address', 'property_address') || pick(b.full_address, c.full_address);

// ---- Attribution ----
const firstAttr = obj(c.attributionSource);
const lastAttr = obj(c.lastAttributionSource);
const topAttr = obj(b.attributionSource);
const a = Object.keys(firstAttr).length ? firstAttr : (Object.keys(topAttr).length ? topAttr : lastAttr);
const fromAny = (key) => pick(a[key], lastAttr[key], topAttr[key]);
const urlParam = (url, name) => {
  const m = String(url || '').match(new RegExp('[?&]' + name + '=([^&#]*)', 'i'));
  if (!m) return '';
  try { return decodeURIComponent(m[1]).trim(); } catch (e) { return m[1].trim(); }
};
const attrUrl = fromAny('url');
const attribution = {
  session_source: fromAny('sessionSource'),
  attribution_url: attrUrl,
  utm_source: fromAny('utmSource') || urlParam(attrUrl, 'utm_source'),
  utm_medium: fromAny('utmMedium') || urlParam(attrUrl, 'utm_medium'),
  utm_campaign: fromAny('utmCampaign') || urlParam(attrUrl, 'utm_campaign'),
  referrer: fromAny('referrer'),
  gclid: fromAny('gclid') || urlParam(attrUrl, 'gclid') || urlParam(lastAttr.url, 'gclid'),
  fbclid: fromAny('fbclid') || urlParam(attrUrl, 'fbclid') || urlParam(lastAttr.url, 'fbclid'),
  fbp: fromAny('fbp'),
  medium: fromAny('medium'),
};
const source = pick(b.contact_source, b.source, c.source, attribution.session_source, attribution.medium, 'GoHighLevel');

// ---- IDs + dedupe key (contact_id, then email, then phone) ----
const ghlContactId = pick(b.contact_id, b.contactId, c.id, c.contact_id);
let contactId = ghlContactId;
if (!contactId) contactId = email ? `email:${email}` : (phone ? `phone:${phone}` : '');

// ---- Validation ----
const reasons = [];
if (!email && !phone) reasons.push(emailRaw || phoneRaw ? 'no usable email or phone' : 'no email or phone');
if (isDisposable) reasons.push(`disposable email domain (${emailDomain})`);
const nameText = fullName.toLowerCase();
const freeText = `${helpTopic} ${message}`.toLowerCase();
if (/https?:\/\/|www\.|<\s*script|\.(com|net|ru|xyz|top)\b/.test(nameText)) reasons.push('junk: link in name');
if (/(.)\1{5,}/.test(nameText.replace(/\s/g, '')) || /^(asdf|qwer|zxcv|jkl;?|sdfg)/.test(nameText.replace(/\s/g, ''))) {
  reasons.push('junk: keyboard mash name');
}
const spamHit = SPAM_PHRASES.find((p) => freeText.includes(p) || nameText.includes(p));
if (spamHit) reasons.push(`junk: spam phrase "${spamHit}"`);
if ((freeText.match(/https?:\/\//g) || []).length >= 3) reasons.push('junk: many links in message');
const valid = reasons.length === 0;

const rawJson = JSON.stringify(b);
const locationId = pick(loc.id, b.location_id, b.locationId, c.locationId);

return [{
  json: {
    valid,
    reason: reasons.join('; '),
    received_at: new Date().toISOString(),
    contact_id: contactId,
    ghl_contact_id: ghlContactId,
    first_name: firstName,
    last_name: lastName,
    full_name: fullName,
    email,
    email_domain: emailDomain,
    phone,
    email_raw: emailRaw,
    phone_raw: phoneRaw,
    property_address: propertyAddress,
    help_topic: helpTopic,
    message,
    website,
    source,
    ...attribution,
    country: pick(b.country, c.country),
    timezone: pick(b.timezone, c.timezone),
    tags: str(b.tags),
    date_created: pick(b.date_created, c.dateAdded),
    contact_type: pick(b.contact_type, c.type),
    location_id: locationId,
    location_name: pick(loc.name, b.location_name),
    raw_json: rawJson.length > 2000 ? rawJson.slice(0, 1997) + '...' : rawJson,
  },
}];

// ============ CONFIG: edit scoring, tiers, tags and pipeline names here ============
const CONFIG = {
  points: {
    validPhone: 20,       // usable phone number
    email: 10,            // usable email address
    businessEmail: 5,     // email domain is not a free provider (gmail, yahoo, ...)
    propertyAddress: 15,  // "Property Address" filled
    helpOrMessage: 10,    // "How can we help?" or "Message" filled
    urgency: 20,          // urgency keyword in message / help topic
    paidTraffic: 10,      // gclid, fbclid, or utm_medium cpc / ppc / paid
    organicReferral: 5,   // organic search, referral or social (only when not paid)
    repeatSubmission: 15, // same contact submitted before
    testOrSpam: -30,      // test / spam pattern in name or email
  },
  urgencyKeywords: ['leak', 'urgent', 'emergency', 'storm', 'damage', 'asap', 'insurance', 'today'],
  paidMediumPattern: /(cpc|ppc|paid|cpm)/i,
  organicPattern: /(organic|referral|social|seo)/i,
  freeEmailDomains: [
    'gmail.com', 'googlemail.com', 'yahoo.com', 'ymail.com', 'hotmail.com', 'outlook.com',
    'live.com', 'msn.com', 'aol.com', 'icloud.com', 'me.com', 'mac.com', 'proton.me',
    'protonmail.com', 'gmx.com', 'gmx.net', 'mail.com', 'zoho.com', 'yandex.com',
    'comcast.net', 'att.net', 'sbcglobal.net', 'verizon.net', 'cox.net', 'charter.net',
  ],
  testNamePattern: /\b(test|testing|tester|asdf|qwerty|fake|dummy|spam|sample|n\/a|none)\b/i,
  testEmailPattern: /^(test|testing|asdf|qwerty|fake|dummy|spam|noreply|no-reply)[0-9._+-]*@|@(test|fake|spam)\.[a-z]+$/i,
  tiers: { hot: 60, warm: 35 }, // hot >= 60, warm 35-59, cold < 35
  tierTags: { hot: 'lead-hot', warm: 'lead-warm', cold: 'lead-cold' },
  scoredTag: 'n8n-scored',
  pipelineName: 'Marketing Pipeline',
  stageNames: { hot: 'Hot Lead', warm: 'New Lead' }, // cold: no opportunity
  opportunitySuffix: 'Roofing estimate',
};
// ===================================================================================

const lead = $('Validate + Normalize').first().json;
// Lookup result: {} when the contact is new (alwaysOutputData), otherwise the existing row.
const prev = ($input.first() && $input.first().json) || {};
const prevId = String(prev.contact_id ?? '').trim();
const isDuplicate = prevId !== '' && prevId === lead.contact_id;
const prevCount = isDuplicate ? (parseInt(prev.submission_count, 10) || 1) : 0;
const now = new Date().toISOString();

const P = CONFIG.points;
let score = 0;
const reasons = [];
const add = (pts, label) => {
  score += pts;
  reasons.push(`${pts > 0 ? '+' : ''}${pts} ${label}`);
};

if (lead.phone) add(P.validPhone, 'valid phone');
if (lead.email) {
  add(P.email, 'email');
  if (lead.email_domain && !CONFIG.freeEmailDomains.includes(lead.email_domain)) add(P.businessEmail, 'business email');
}
if (lead.property_address) add(P.propertyAddress, 'property address');
if (lead.help_topic || lead.message) add(P.helpOrMessage, 'help topic / message');

const text = `${lead.help_topic} ${lead.message}`.toLowerCase();
const urgentHits = CONFIG.urgencyKeywords.filter((k) => new RegExp(`\\b${k}`, 'i').test(text));
if (urgentHits.length) add(P.urgency, `urgency (${urgentHits.join(', ')})`);

const isPaid = !!(lead.gclid || lead.fbclid || CONFIG.paidMediumPattern.test(lead.utm_medium || '')
  || /paid/i.test(lead.session_source || ''));
const isOrganic = !isPaid && (CONFIG.organicPattern.test(lead.utm_medium || '')
  || CONFIG.organicPattern.test(lead.session_source || '') || !!lead.referrer);
if (isPaid) add(P.paidTraffic, 'paid traffic');
else if (isOrganic) add(P.organicReferral, 'organic / referral');

if (isDuplicate) add(P.repeatSubmission, `repeat submission (#${prevCount + 1})`);

const emailLocalTest = CONFIG.testEmailPattern.test(lead.email || lead.email_raw || '');
if (CONFIG.testNamePattern.test(lead.full_name || '') || emailLocalTest) add(P.testOrSpam, 'test / spam pattern');

score = Math.max(0, Math.min(100, score));
const tier = score >= CONFIG.tiers.hot ? 'hot' : (score >= CONFIG.tiers.warm ? 'warm' : 'cold');
const tierTag = CONFIG.tierTags[tier];
const displayName = lead.full_name || lead.email || lead.phone || 'Unknown';

return [{
  json: {
    ...lead,
    is_duplicate: isDuplicate,
    submission_count: prevCount + 1,
    first_seen: isDuplicate ? (String(prev.first_seen || '').trim() || now) : now,
    last_seen: now,
    score,
    tier,
    score_reasons: reasons.join(', ') || 'no scoring signals',
    // GHL sync instructions (used by the HTTP Request nodes)
    has_ghl_id: !!lead.ghl_contact_id,
    tags_to_add: [tierTag, CONFIG.scoredTag],
    tags_to_remove: Object.values(CONFIG.tierTags).filter((t) => t !== tierTag),
    wants_opportunity: !!CONFIG.stageNames[tier],
    pipeline_name: CONFIG.pipelineName,
    stage_name: CONFIG.stageNames[tier] || '',
    opportunity_name: `${displayName} - ${CONFIG.opportunitySuffix} (score ${score})`,
  },
}];

// Pick the pipeline + stage by case-insensitive name (names come from CONFIG in "Score Lead").
const lead = $('Score Lead').first().json;
const res = ($input.first() && $input.first().json) || {};
const norm = (s) => String(s ?? '').trim().toLowerCase();
const errMsg = (e) => (typeof e === 'string' ? e : (e && (e.message || e.description)) || JSON.stringify(e));

let error = '';
let pipelineId = '';
let stageId = '';
if (res.error) {
  error = `get pipelines: ${errMsg(res.error)}`;
} else {
  const pipelines = Array.isArray(res.pipelines) ? res.pipelines : [];
  const pipeline = pipelines.find((p) => norm(p.name) === norm(lead.pipeline_name));
  if (!pipeline) {
    error = `pipeline "${lead.pipeline_name}" not found`;
  } else {
    pipelineId = pipeline.id || '';
    const stage = (Array.isArray(pipeline.stages) ? pipeline.stages : [])
      .find((s) => norm(s.name) === norm(lead.stage_name));
    if (!stage) error = `stage "${lead.stage_name}" not found in "${pipeline.name}"`;
    else stageId = stage.id || '';
  }
}

return [{
  json: {
    stage_found: !error && !!pipelineId && !!stageId,
    pick_error: error,
    upsert_body: {
      pipelineId,
      locationId: lead.location_id,
      contactId: lead.ghl_contact_id,
      pipelineStageId: stageId,
      status: 'open',
      name: lead.opportunity_name,
    },
  },
}];

// Combine the lead with the result of every GHL step that ran, then build the Telegram text.
const lead = $('Score Lead').first().json;

// Output of a node, or null if it did not run in this execution.
const out = (name) => {
  try {
    const it = $(name).first();
    return it ? (it.json || {}) : null;
  } catch (e) {
    return null;
  }
};
const errMsg = (e) => (typeof e === 'string' ? e : (e && (e.message || e.description)) || JSON.stringify(e));

let ghlSync = 'skipped';
let opportunityId = '';
if (lead.has_ghl_id) {
  const errors = [];
  const steps = [['remove tags', 'GHL Remove Tier Tags'], ['add tags', 'GHL Add Tier Tags']];
  for (const [label, node] of steps) {
    const r = out(node);
    if (r === null) errors.push(`${label}: did not run`);
    else if (r.error) errors.push(`${label}: ${errMsg(r.error)}`);
  }
  if (lead.wants_opportunity) {
    if (!lead.location_id) {
      errors.push('opportunity: no location.id in webhook');
    } else {
      const pick = out('Pick Pipeline Stage');
      const pipes = out('GHL Get Pipelines');
      if (pick && pick.pick_error) {
        errors.push(pick.pick_error);
      } else if (!pick) {
        errors.push(pipes && pipes.error ? `get pipelines: ${errMsg(pipes.error)}` : 'opportunity: pipeline lookup did not run');
      } else {
        const up = out('GHL Upsert Opportunity');
        if (up === null) errors.push('opportunity: upsert did not run');
        else if (up.error) errors.push(`opportunity: ${errMsg(up.error)}`);
        else opportunityId = String((up.opportunity && up.opportunity.id) || up.id || '');
      }
    }
  }
  ghlSync = errors.length ? `failed: ${errors.join('; ')}`.slice(0, 500) : 'ok';
}

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const contactUrl = lead.location_id && lead.ghl_contact_id
  ? `https://app.gohighlevel.com/v2/location/${encodeURIComponent(lead.location_id)}/contacts/detail/${encodeURIComponent(lead.ghl_contact_id)}`
  : '';
const lines = [
  `🔥 <b>HOT roofing lead</b> — score ${lead.score}/100` + (lead.location_name ? ` (${esc(lead.location_name)})` : ''),
  '',
  `👤 <b>Name:</b> ${esc(lead.full_name || '—')}`,
  `📞 <b>Phone:</b> ${esc(lead.phone || '—')}`,
  `📧 <b>Email:</b> ${esc(lead.email || '—')}`,
  `🏠 <b>Address:</b> ${esc(lead.property_address || '—')}`,
];
if (lead.help_topic) lines.push(`🛠 <b>Help:</b> ${esc(lead.help_topic)}`);
if (lead.message) lines.push(`💬 <b>Message:</b> ${esc(lead.message.length > 500 ? lead.message.slice(0, 497) + '...' : lead.message)}`);
lines.push(
  `📊 <b>Why:</b> ${esc(lead.score_reasons)}`,
  `🔁 <b>Duplicate:</b> ${lead.is_duplicate ? `yes (submission #${lead.submission_count})` : 'no'}`,
  `🔗 <b>Source:</b> ${esc(lead.source || '—')}`,
);
if (ghlSync !== 'ok') lines.push(`⚠️ <b>GHL sync:</b> ${esc(ghlSync)}`);
lines.push(contactUrl ? `\n<a href="${esc(contactUrl)}">Open contact in GHL</a>` : `\n🆔 <code>${esc(lead.contact_id)}</code>`);

return [{
  json: {
    ...lead,
    ghl_sync: ghlSync,
    ghl_opportunity_id: opportunityId,
    contact_url: contactUrl,
    telegram_text: lines.join('\n'),
  },
}];
